def resolve(path, cwd, links):
    if links is None:
        links = {}

    # Start with the initial path
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    # Track number of links followed
    links_followed = 0

    # Split remaining path into components
    components = remaining.split('/') if remaining else []

    while True:
        # Process next component
        if not components:
            break

        component = components.pop(0)

        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current != '/':
                # Remove the last component from current path
                parts = current.rstrip('/').split('/')
                if parts:
                    parts.pop()
                current = '/' + '/'.join(parts[1:]) if parts[1:] else '/'
            continue

        # Append the component to current path
        if current == '/':
            potential = '/' + component
        else:
            potential = current + '/' + component

        # Check if this is a symlink
        if potential in links:
            # Follow the link
            links_followed += 1
            if links_followed > 8:
                return None

            target = links[potential]

            # Resolve the target relative to the directory containing the link
            if target.startswith('/'):
                # Absolute target
                current = '/'
                new_components = target[1:].split('/') if target[1:] else []
            else:
                # Relative target - relative to the directory containing the link
                if potential == '/':
                    link_dir = '/'
                else:
                    link_parts = potential.rstrip('/').split('/')
                    link_parts.pop()
                    link_dir = '/' + '/'.join(link_parts[1:]) if link_parts[1:] else '/'

                current = link_dir
                new_components = target.split('/') if target else []

            # Add remaining components to the front
            components = new_components + components
        else:
            # Regular path component
            current = potential

    # Return the result without trailing slash (except for '/')
    if current == '/':
        return '/'
    return current.rstrip('/')

